import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"54、【归妹】 兑下震上","description":"横渠易说 - 54、【归妹】 兑下震上","frontmatter":{"title":"54、【归妹】 兑下震上","description":"横渠易说 - 54、【归妹】 兑下震上"},"headers":[],"relativePath":"zh/classics/hengqu/056.md","filePath":"zh/classics/hengqu/056.md"}'),l={name:"zh/classics/hengqu/056.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_54、【归妹】-兑下震上" tabindex="-1">54、【归妹】 兑下震上 <a class="header-anchor" href="#_54、【归妹】-兑下震上" aria-label="Permalink to “54、【归妹】 兑下震上”">​</a></h1><h3 id="彖曰-归妹-天地之大义也-天地不交而万物不兴-归妹-人之终始也-说以动-所归妹也。-征凶-位不当也-无攸利-柔乘刚也。" tabindex="-1">彖曰：归妹，天地之大义也，天地不交而万物不兴，归妹，人之终始也，说以动，所归妹也。“征凶”，位不当也；“无攸利”，柔乘刚也。 <a class="header-anchor" href="#彖曰-归妹-天地之大义也-天地不交而万物不兴-归妹-人之终始也-说以动-所归妹也。-征凶-位不当也-无攸利-柔乘刚也。" aria-label="Permalink to “彖曰：归妹，天地之大义也，天地不交而万物不兴，归妹，人之终始也，说以动，所归妹也。“征凶”，位不当也；“无攸利”，柔乘刚也。”">​</a></h3><p>泰之九三进而在四，六四降而在三，故曰“天地之大义”也。然泰道将终，征将为否，故曰“凶”。 三五皆乘刚，必退反乃吉。 归妹与革，均是泽为大卦，义不相乾，故革具四德而归妹初不言德也。妹者是少女之称也，对长男而言之，故言少女。先儒谓侄娣之义于卦不见，于爻辞则有君与娣之称。长男而与长女，是人之常也；少女而与少男，是人之感也。说以动须是归妹，圣人直是尽人情。</p><h3 id="象曰-泽上有雷-归妹-君子以永终知敝。" tabindex="-1">象曰：泽上有雷，归妹，君子以永终知敝。 <a class="header-anchor" href="#象曰-泽上有雷-归妹-君子以永终知敝。" aria-label="Permalink to “象曰：泽上有雷，归妹，君子以永终知敝。”">​</a></h3><p>永常礼之终，知人情之敝。</p><h3 id="初九-归妹以娣-跛能履-征吉。-象曰-归妹以娣-以恒也-跛能履吉-相承也。" tabindex="-1">初九，归妹以娣，跛能履，征吉。 象曰：“归妹以娣”，以恒也；“跛能履吉”，相承也。 <a class="header-anchor" href="#初九-归妹以娣-跛能履-征吉。-象曰-归妹以娣-以恒也-跛能履吉-相承也。" aria-label="Permalink to “初九，归妹以娣，跛能履，征吉。 象曰：“归妹以娣”，以恒也；“跛能履吉”，相承也。”">​</a></h3><p>阳处于上，不可不随，故征吉，以兑应震，合卦之义，常道也。爻为阳故能履，非匹故跛。</p><h3 id="九二-眇能视-利幽人之贞。-象曰-利幽人之贞-未变常也。" tabindex="-1">九二，眇能视，利幽人之贞。 象曰：“利幽人之贞”，未变常也。 <a class="header-anchor" href="#九二-眇能视-利幽人之贞。-象曰-利幽人之贞-未变常也。" aria-label="Permalink to “九二，眇能视，利幽人之贞。 象曰：“利幽人之贞”，未变常也。”">​</a></h3><p>震动乎上，虽匹而不至，所以眇，阳中，故能视。不援上，幽人之贞也。</p><h3 id="六三-归妹以须-反归以娣。-象曰-归妹以须-未当也。" tabindex="-1">六三，归妹以须，反归以娣。 象曰：“归妹以须”，未当也。 <a class="header-anchor" href="#六三-归妹以须-反归以娣。-象曰-归妹以须-未当也。" aria-label="Permalink to “六三，归妹以须，反归以娣。 象曰：“归妹以须”，未当也。”">​</a></h3><p>三阴本汇征在上，今六三反下而为兑，故曰“归妹以须，反归以娣”。女当待年于家，今待年夫家而反归，故曰“未当”。</p><h3 id="九四-归妹愆期-迟归有时。-象曰-愆期之志-有待而行也。" tabindex="-1">九四，归妹愆期，迟归有时。 象曰：愆期之志，有待而行也。 <a class="header-anchor" href="#九四-归妹愆期-迟归有时。-象曰-愆期之志-有待而行也。" aria-label="Permalink to “九四，归妹愆期，迟归有时。 象曰：愆期之志，有待而行也。”">​</a></h3><p>九四当速交而为泰，今独后者，三有所待也，故曰“愆期”。</p><h3 id="六五-帝乙归妹-其君之袂不如其娣之袂良-月几望-吉。-象曰-帝乙归妹-不如其娣之袂良也-其位在中-以贵行也。" tabindex="-1">六五，帝乙归妹，其君之袂不如其娣之袂良，月几望，吉。 象曰：“帝乙归妹”，不如其娣之袂良也；其位在中，以贵行也。 <a class="header-anchor" href="#六五-帝乙归妹-其君之袂不如其娣之袂良-月几望-吉。-象曰-帝乙归妹-不如其娣之袂良也-其位在中-以贵行也。" aria-label="Permalink to “六五，帝乙归妹，其君之袂不如其娣之袂良，月几望，吉。 象曰：“帝乙归妹”，不如其娣之袂良也；其位在中，以贵行也。”">​</a></h3><p>归妹，交泰之事备矣，与泰六五同，又于此见□□为之戒也。以其贵行，故戒其满以几望。一作又于此见新故之戒也。</p><h3 id="上六-女承筐无实-士刲羊无血-无攸利。-象曰-上六无实-承虚筐也。" tabindex="-1">上六，女承筐无实，士刲羊无血，无攸利。 象曰：上六无实，承虚筐也。 <a class="header-anchor" href="#上六-女承筐无实-士刲羊无血-无攸利。-象曰-上六无实-承虚筐也。" aria-label="Permalink to “上六，女承筐无实，士刲羊无血，无攸利。 象曰：上六无实，承虚筐也。”">​</a></h3><p>上六与六三皆阴，故士女无实。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
